def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids)
    labs = sorted(set(feats.stratum))
    S = np.column_stack([np.ones(n)] + [np.array([s == l for s in feats.stratum], float) for l in labs[1:]])
    def ll(Z):
        A = np.column_stack([S, Z]) if Z is not None and Z.size else S
        b = np.zeros(A.shape[1])
        for _ in range(30):
            pr = 1 / (1 + np.exp(-np.clip(A @ b, -30, 30)))
            H = A.T @ (A * (pr * (1 - pr))[:, None]) + 1e-6 * np.eye(A.shape[1])
            st = np.linalg.solve(H, A.T @ (y - pr)); b += st
            if np.abs(st).max() < 1e-7: break
        pr = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(pr) + (1 - y) * np.log(1 - pr)))
    R = np.corrcoef(X.T); R = np.nan_to_num(R)
    def M(sel): return X[:, sel] if sel else None
    def gain(sel, j): return 2 * (ll(X[:, sel + [j]]) - ll(M(sel)))
    sel = []
    while len(sel) < MAX_DRIVERS:
        cand = [j for j in range(p) if j not in sel and all(abs(R[j, k]) < 0.6 for k in sel)]
        if not cand: break
        g = np.array([gain(sel, j) for j in cand])
        a = (0.1 if not sel else 0.02) / p
        if stats.chi2.sf(g.max(), 1) > a: break
        sel.append(cand[int(g.argmax())])
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (ll(X[:, sel]) - ll(M(rest))), 1) > 0.01 / p:
                sel.remove(j); changed = True; break
    for i, j in enumerate(list(sel)):
        rest = [k for k in sel if k != j]
        cl = {j}; fr = {j}
        for _ in range(2):
            fr = {k for f in fr for k in range(p) if abs(R[f, k]) >= 0.6 and k not in rest} - cl; cl |= fr
        if len(cl) > 1:
            cl = sorted(cl)
            L = np.array([ll(X[:, rest + [c]]) for c in cl])
            sc = [-sum(abs(R[c, m]) for m in cl if m != c) + (1e9 if 2 * (L.max() - L[q]) > 3.0 else 0) for q, c in enumerate(cl)]
            sel[i] = cl[int(np.argmin(sc))]
    prods = []
    base = ll(M(sel))
    tests = []
    for a in range(p):
        for b in range(a, p):
            if a != b and abs(R[a, b]) >= 0.6: continue
            mains = sorted(set(sel) | {a, b})
            Z = X[:, mains]; w = X[:, a] * X[:, b]
            l0 = ll(Z) if not (a in sel and b in sel) else base
            tests.append((2 * (ll(np.column_stack([Z, w])) - l0), a, b))
    tests.sort(reverse=True)
    thr = 0.01 / (p * (p + 1) / 2); used = set()
    for g, a, b in tests[:5]:
        if stats.chi2.sf(g, 1) < thr and not ({a, b} & used) and len(prods) < 2:
            prods.append((a, b)); used |= {a, b}
    drivers = list(sel)
    for a, b in prods:
        for k in (a, b):
            if k not in drivers: drivers.append(k)
    drivers = drivers[:MAX_DRIVERS]
    cols = sorted(set(sel) | {k for pr in prods for k in pr})
    return Design(drivers=tuple(ids[k] for k in drivers), columns=tuple(ids[k] for k in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

